<?php
require __DIR__ . '/app/bootstrap.php';
$id=max(0,(int)($_GET['id']??0));$product=get_product($pdo,$id);
if(!$product){http_response_code(404);render_header('محصول پیدا نشد');echo '<main class="container page-title"><h1>محصول پیدا نشد</h1><a class="btn" href="'.e(site_url('products.php')).'">بازگشت به محصولات</a></main>';render_footer();exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$qty=max(1,min(99,(int)($_POST['qty']??1)));$_SESSION['cart'][$id]=min(99,(int)($_SESSION['cart'][$id]??0)+$qty);$selected=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['options']??[])))));$_SESSION['cart_options'][$id]=array_fill_keys($selected,1);flash('success','محصول به سبد خرید اضافه شد.');header('Location: '.site_url('cart.php'));exit;}
$oq=$pdo->prepare('SELECT * FROM print_options WHERE is_active=1 AND (product_id IS NULL OR product_id=?) ORDER BY option_group,sort_order,id');$oq->execute([$id]);$printOptions=$oq->fetchAll();
render_header($product['name']);
?>
<main class="container"><div class="detail"><img src="<?=e(product_image($product['image']))?>" alt="<?=e($product['name'])?>"><div><span class="eyebrow"><?=e($product['category'])?></span><h1><?=e($product['name'])?></h1><p><?=nl2br(e($product['description']))?></p><div class="price"><?=((int)$product['price']>0)?money($product['price']):'استعلام قیمت'?></div><?php if(!empty($product['tirages'])): ?><div class="detail-tirages"><strong>تیراژهای قابل سفارش</strong><?php foreach(explode('|',(string)$product['tirages']) as $idx=>$set): ?><div class="tirage-set"><?php if(str_contains((string)$product['tirages'],'|')): ?><span class="tirage-set-label"><?= $idx===0?'سری اول':'سری دوم' ?></span><?php endif; ?><?php foreach(array_filter(array_map('trim',explode('،',trim($set)))) as $num): ?><span class="tirage-chip"><?=e($num)?></span><?php endforeach; ?></div><?php endforeach; ?></div><?php endif; ?><p>قیمت نهایی با توجه به تیراژ و مشخصات چاپ اعلام می‌شود.</p><?php if((int)$product['price']>0): ?><form method="post" class="inline-form" style="display:block"><?=csrf_field()?><?php if($printOptions): ?><div class="form-grid" style="margin:18px 0"><?php foreach($printOptions as $op): ?><div class="form-group"><label><input type="checkbox" name="options[]" value="<?=$op['id']?>"> <?=e($op['option_group'])?>: <?=e($op['option_name'])?> (<?=((int)$op['price_delta']>=0?'+':'').money($op['price_delta'])?>)</label></div><?php endforeach; ?></div><?php endif; ?><label>تعداد <input class="qty" type="number" name="qty" min="1" max="99" value="1"></label> <button class="btn">افزودن به سبد خرید</button></form><?php else: ?><div class="notice">قیمت این محصول هنوز ثبت نشده است؛ برای دریافت قیمت و ثبت سفارش با ما تماس بگیرید.</div><a class="btn" href="<?=e(site_url('contact.php'))?>">درخواست استعلام قیمت</a><?php endif; ?><div class="notice">برای سفارش‌های سفارشی، فایل چاپی و جزئیات نهایی باید پیش از تولید بررسی شوند.</div></div></div></main>
<?php render_footer(); ?>
